import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { type ContractName, contractNames } from "../src/contract-names";

export const rootDir = join(__dirname, "..");

const artifactsDir = join(rootDir, "artifacts/contracts");

export const abiExportNames: Record<ContractName, string> = {
  IdentityRegistry: "identityRegistryAbi",
  IdentityRegistryMirror: "identityRegistryMirrorAbi",
  ComplianceRules: "complianceRulesAbi",
  CompliantERC20: "compliantErc20Abi",
};

/** A generated file, with its path relative to the repository root. */
export type AbiFile = { path: string; contents: string };

const generatedHeader =
  "// Generated by scripts/export-abi.ts from the compiled Hardhat artifacts. Do not edit.\n";

function readArtifactAbi(contract: ContractName): unknown[] {
  const candidates = [
    join(artifactsDir, `core/${contract}.sol/${contract}.json`),
    join(artifactsDir, `compliance/${contract}.sol/${contract}.json`),
    join(artifactsDir, `tokens/${contract}.sol/${contract}.json`),
    join(artifactsDir, `interfaces/I${contract}.sol/I${contract}.json`),
  ];

  const artifactPath = candidates.find((path) => existsSync(path));
  if (!artifactPath) {
    throw new Error(`No compiled artifact for ${contract}. Run \`bun run compile\` first.`);
  }

  return JSON.parse(readFileSync(artifactPath, "utf8")).abi;
}

/**
 * Renders every published ABI file from the compiled artifacts: the JSON ABI
 * under `abi/` and a const-typed TypeScript module under `src/abi/`, so viem
 * and wagmi can infer function names, arguments, and return types.
 */
export function renderAbiFiles(): AbiFile[] {
  const files: AbiFile[] = [];

  for (const contract of contractNames) {
    const abiJson = JSON.stringify(readArtifactAbi(contract), null, 2);

    files.push({ path: `abi/${contract}.json`, contents: `${abiJson}\n` });
    files.push({
      path: `src/abi/${contract}.ts`,
      contents: `${generatedHeader}\nimport type { Abi } from "viem";\n\nexport const ${abiExportNames[contract]} = ${abiJson} as const satisfies Abi;\n`,
    });
  }

  const reexports = contractNames
    .map((contract) => `export { ${abiExportNames[contract]} } from "./${contract}";`)
    .join("\n");
  files.push({ path: "src/abi/index.ts", contents: `${generatedHeader}\n${reexports}\n` });

  return files;
}
